+
+    test('dispatcher routes gitlab_list_project_jobs (not Unsupported)', () {
+      final dispatcher = SyncToolDispatcher(PropertyReader());
+      final result = dispatcher.execute('gitlab_list_project_jobs', {
+        'workspace': 'g',
+        'repository': 'r',
