  Map<String, _GitlabExecutor> fns,
) =>
    {
      for (final entry in fns.entries)
        entry.key: (args) {
          final config = _gitlabConfig();
          if (config == null) return syncErr('GitLab not configured');
          return entry.value(config, args);
        },
    };

