blocks.text:
/// JS sync-surface parity: every canonical MCP tool must either resolve to
/// a [SyncToolDispatcher] handler or be an acknowledged gap in the frozen
/// ratchet list.
///
/// Why: the JS bridge generates a global wrapper for EVERY registry tool
/// (`ToolWrapperGenerator` — agent scripts see all 420 functions), but the
/// call dispatches through the sync layer; a tool without a sync handler
/// dies at runtime with `Unsupported tool` (exactly how
/// `gitlab_get_mr_pipelines` slipped through Java #574 → #159). This test
/// makes that hole impossible to add silently:
///
/// - a NEW tool without a sync executor fails the test (list mismatch);
/// - a CLOSED gap that is not removed from the list fails the test too
///   (the ratchet only shrinks, both directions enforced).
///
/// A "hole" is: `null` from the dispatcher (no handler → `Tool not
/// available` upstream), or an error envelope naming the tool Unsupported/
/// Unknown. An `<integration> not configured` envelope means the handler
/// EXISTS (config is absent in the test env) — that is the healthy answer.
/// Executor argument-validation exceptions likewise prove a handler exists.
library;

import 'dart:io';

import 'package:dmtools/src/config/property_reader.dart';
import 'package:dmtools/src/js/sync_tool_dispatcher.dart';
import 'package:dmtools/src/mcp/default_tool_registry.dart';
import 'package:test/test.dart';

const _gapsPath = 'test/fixtures/js_sync_surface_gaps.txt';

void main() {
  test(
      'every canonical MCP tool reaches a JS sync handler (ratcheted '
      'gaps only)', () {
    PropertyReader.testIsolation = true;
    addTearDown(() => PropertyReader.testIsolation = false);

    final registry = createDefaultToolRegistry();
    final dispatcher = SyncToolDispatcher(PropertyReader());

    final holes = <String>{};
    for (final tool in registry.allTools) {
      if (_isHole(dispatcher, tool.name)) holes.add(tool.name);
    }

    final frozen = _frozenGaps();
    expect(frozen, isNotEmpty, reason: 'fixture missing: $_gapsPath');

    final newHoles = holes.difference(frozen).toList()..sort();
    final stale = frozen.difference(holes).toList()..sort();

    expect(
      newHoles,
      isEmpty,
      reason: 'New MCP tools without JS sync executors — these names get a '
          'generated JS wrapper but die with "Unsupported tool" at call '
          'time. Implement the sync executor or (if deliberate) append to '
          '$_gapsPath:\n${newHoles.join('\n')}',
    );
    expect(
      stale,
      isEmpty,
      reason: 'Closed gaps still frozen in $_gapsPath — the ratchet only '
          'shrinks; remove the resolved names in the same PR:\n'
          '${stale.join('\n')}',
    );

    // ignore: avoid_print, audit trail on every run
    print(
      'js sync surface: ${registry.allTools.length} canonical tools, '
      '${holes.length} ratcheted gaps, '
      '${registry.allTools.length - holes.length} live handlers',
    );
  });
}

/// Whether [tool] fails to reach a sync executor: `null` (no handler) or
/// an Unsupported/Unknown-tool error envelope. Config-missing envelopes and
/// thrown validation errors both prove a handler exists.
====
/// Phase 3 "CI comparison green" gate — Dart vs. Java MCP tool catalog.
///
/// Compares the Dart catalog from [createDefaultToolRegistry] against the Java
/// reference catalog extracted from the `@MCPTool` annotations in
/// `dm.ai/dmtools-core` (see `test/fixtures/java_mcp_tool_names.txt`). Every
/// Java tool must be accounted for by one of:
///
/// 1. an **exact** name match in the Dart registry, or
/// 2. a **documented naming-convention equivalent** (see below), or
/// 3. an entry in the **frozen gap snapshot** (`java_mcp_tool_gaps.txt`).
///
/// Tool **parameter names** get the same treatment (gh-123: a param renamed on
/// one side only — Java `statusName` vs Dart `status` — was invisible to a
/// name-only comparison):
///
/// - `java_mcp_tool_params.txt` — exact-name matches whose parameter names
///   match Java; parity is enforced per line.
/// - `java_mcp_param_drift.txt` — exact-name matches whose parameter names
///   still diverge (the param-side counterpart of the gap snapshot); each
///   listed tool must still diverge.
/// - Every exact-name match from the names fixture must appear in exactly one
///   of the two files, so newly ported tools cannot skip classification.
///
/// Regenerate both files from a fresh Java checkout with
/// `python3 scripts/extract_java_tool_params.py <tools-raw.json>`.
///
/// The documented naming conventions the Dart port deliberately diverges on:
///
/// - **AI**: Dart exposes both the unified `ai_chat` family and the
///   per-provider tools Java has (`openai_ai_chat`, `gemini_ai_chat`,
///   `anthropic_ai_chat`, …) — those match exactly. Remaining Java AI
///   variants (`*_ai_chat_with_files`, `*_list_models`,
///   `vertex_ai_gemini_chat`) map onto `ai_chat_with_history` /
///   `ai_list_models`.
/// - **Teams**: Java exposes `teams_*_raw` variants that return unprocessed
///   Graph JSON. Dart drops the `_raw` suffix when the consolidated tool covers
///   the same shape.
///
/// The snapshot test stays green while the gap is unchanged. Port a Java tool
/// and it turns red, prompting the gap to shrink; re-extract the fixture from a
/// newer Java build and it turns red if new unported tools appear.
library;

import 'dart:io';

import 'package:dmtools/dmtools.dart';
import 'package:test/test.dart';

void main() {
  final javaNames = _readFixture('java_mcp_tool_names.txt');
  final dartTools = createDefaultToolRegistry().allTools;
  final dartNames = dartTools.map((t) => t.name).toSet();
  final frozenGaps = _readFixture('java_mcp_tool_gaps.txt');

  fixtureSanityTests(javaNames, dartNames);
  paritySnapshotTests(javaNames, dartNames, frozenGaps);
  equivalentMappingTests(javaNames, dartNames);
  parameterParityTests(dartTools);
}

